// Quest loot bags: opening a bag rolls a rarity with that bag's odds (lootBagOdds, generated by
// tools/build_quest_bags.py into strata_loot_bag_odds.js), then one item from the rarity's loot table
// (strata:loot_bags/<rarity>). Each rarity has its own colour and sound; a Legendary roll is
// announced to the whole server.
const lootBagParamsBuilder = Java.loadClass('net.minecraft.world.level.storage.loot.LootParams$Builder')
const lootBagParams = Java.loadClass('net.minecraft.world.level.storage.loot.parameters.LootContextParams')
const lootBagParamSets = Java.loadClass('net.minecraft.world.level.storage.loot.parameters.LootContextParamSets')
const lootBagResourceKey = Java.loadClass('net.minecraft.resources.ResourceKey')
const lootBagRegistries = Java.loadClass('net.minecraft.core.registries.Registries')
const lootBagRL = Java.loadClass('net.minecraft.resources.ResourceLocation')

const lootBagRarities = {
  common: { name: 'Common', text: s => Text.white(s), sound: 'minecraft:item.bundle.drop_contents' },
  uncommon: { name: 'Uncommon', text: s => Text.green(s), sound: 'minecraft:entity.experience_orb.pickup' },
  rare: { name: 'Rare', text: s => Text.aqua(s), sound: 'minecraft:entity.player.levelup' },
  epic: { name: 'Epic', text: s => Text.lightPurple(s), sound: 'minecraft:ui.toast.challenge_complete' },
  legendary: { name: 'Legendary', text: s => Text.gold(s).bold(true), sound: 'minecraft:ui.toast.challenge_complete' },
}

function lootBagRollRarity(weights) {
  const names = Object.keys(weights)
  const total = names.reduce((sum, n) => sum + weights[n], 0)
  let roll = Math.random() * total
  for (let i = 0; i < names.length; i++) {
    roll -= weights[names[i]]
    if (roll < 0) return names[i]
  }
  return names[names.length - 1]
}

function lootBagRollItems(player, rarity) {
  const level = player.level
  const key = lootBagResourceKey.create(lootBagRegistries.LOOT_TABLE, lootBagRL.parse(`strata:loot_bags/${rarity}`))
  const table = level.server.reloadableRegistries().getLootTable(key)
  const params = new lootBagParamsBuilder(level)
    .withParameter(lootBagParams.ORIGIN, player.position())
    .withOptionalParameter(lootBagParams.THIS_ENTITY, player)
    .withLuck(player.getLuck())
    .create(lootBagParamSets.CHEST)
  const out = []
  const rolled = table.getRandomItems(params)
  for (let i = 0; i < rolled.size(); i++) {
    let stack = rolled.get(i)
    if (!stack.isEmpty()) out.push(stack)
  }
  return out
}

function lootBagOpen(player, bag, bagId) {
  const rarity = lootBagRollRarity(lootBagOdds[bagId])
  const r = lootBagRarities[rarity]
  const items = lootBagRollItems(player, rarity)
  const names = items.map(s => `${s.count}x ${s.hoverName.string}`).join(', ')
  items.forEach(s => player.give(s))
  bag.shrink(1)
  player.server.runCommandSilent(`execute as ${player.username} at @s run playsound ${r.sound} player @s`)
  player.tell(r.text(`[${r.name}] `).append(Text.white(names || 'nothing')))
  if (rarity === 'legendary') {
    player.server.tell(Text.gold(`${player.username} opened a Legendary loot bag: `).append(Text.white(names)))
  }
}

Object.keys(lootBagOdds).forEach(bagId => {
  ItemEvents.rightClicked(bagId, event => {
    lootBagOpen(event.player, event.item, bagId)
    event.cancel()
  })
})
